I pulled the iOS (`apple-hig`) and Android (`material-3`) platform rules plus the dark-mode token ladder before writing this, since it's a native screen shipping on both OSes. Here's the complete, self-contained screen.

Key platform decisions baked in:
- **Touch targets:** every row is `minHeight: 48` — satisfies iOS's 44pt floor and Android's 48dp floor at once.
- **Confirmation dialog:** uses RN's built-in `Alert.alert`, which renders a native `UIAlertController` (destructive red button, separate Cancel) on iOS and a native two-action Material dialog on Android — exactly what each platform's own guidance asks for, with no extra code per platform.
- **Dark mode:** colors follow the elevation ladder (app background darkest, surfaces step lighter, never pure black, no shadows for separation — tonal surfaces only, per Material 3/HIG agreement).
- **No in-screen back button/header** — assumes this is pushed by a stack navigator that already supplies back navigation, so it isn't duplicated (both HIG and Material explicitly forbid a second back control).
- **Dynamic Type/RTL safety:** no fixed row heights or truncated labels, chevron glyph flips for RTL.
- Uses `react-native-safe-area-context` (already a transitive dependency of React Navigation in most RN apps) for insets — no other third-party deps.

```tsx
// AccountSettingsScreen.tsx
import React, { useMemo, useState } from 'react';
import {
  View,
  Text,
  Image,
  Pressable,
  Switch,
  ScrollView,
  Alert,
  ActivityIndicator,
  StatusBar,
  StyleSheet,
  useColorScheme,
  I18nManager,
  Platform,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

// --- Theme tokens -----------------------------------------------------
// Dark values step lighter per surface level (app < surface < raised),
// never pure black, per the Material 3 / HIG elevation ladder.
const palettes = {
  light: {
    bgApp: '#F2F2F7',
    bgSurface: '#FFFFFF',
    bgSurfaceRaised: '#FFFFFF',
    textPrimary: '#1C1C1E',
    textMuted: '#6C6C70',
    borderSubtle: '#E3E3E8',
    accentSolid: '#007AFF',
    dangerText: '#FF3B30',
  },
  dark: {
    bgApp: '#121214',
    bgSurface: '#1C1C1E',
    bgSurfaceRaised: '#242428',
    textPrimary: '#FFFFFF',
    textMuted: '#9A9A9E',
    borderSubtle: '#38383A',
    accentSolid: '#0A84FF',
    dangerText: '#FF453A',
  },
} as const;

type Tokens = typeof palettes.light;

function useTokens(): Tokens {
  const scheme = useColorScheme();
  return scheme === 'dark' ? palettes.dark : palettes.light;
}

// --- Row model ----------------------------------------------------------

type NavRow = {
  id: string;
  type: 'navigation';
  label: string;
  value?: string;
  onPress: () => void;
};

type ToggleRow = {
  id: string;
  type: 'toggle';
  label: string;
  value: boolean;
  onToggle: (next: boolean) => void;
};

type DestructiveRow = {
  id: string;
  type: 'destructive';
  label: string;
  busy?: boolean;
  onPress: () => void;
};

type SettingsRow = NavRow | ToggleRow | DestructiveRow;

type Section = {
  id: string;
  title?: string;
  rows: SettingsRow[];
};

// --- Public props --------------------------------------------------------

export interface AccountSettingsScreenProps {
  user: {
    name: string;
    email: string;
    avatarUri?: string;
  };
  onEditProfile: () => void;
  onChangePassword: () => void;
  onOpenPrivacy: () => void;
  onOpenLanguage: () => void;
  onOpenHelp: () => void;
  notificationsEnabled: boolean;
  onToggleNotifications: (next: boolean) => void;
  biometricEnabled: boolean;
  onToggleBiometric: (next: boolean) => void;
  onSignOut: () => void;
  onDeleteAccount: () => Promise<void>;
}

const CHEVRON = I18nManager.isRTL ? '\u2039' : '\u203A';

export default function AccountSettingsScreen({
  user,
  onEditProfile,
  onChangePassword,
  onOpenPrivacy,
  onOpenLanguage,
  onOpenHelp,
  notificationsEnabled,
  onToggleNotifications,
  biometricEnabled,
  onToggleBiometric,
  onSignOut,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const tokens = useTokens();
  const styles = useMemo(() => createStyles(tokens), [tokens]);
  const insets = useSafeAreaInsets();
  const scheme = useColorScheme();
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDeleteAccount = async () => {
    setIsDeleting(true);
    try {
      await onDeleteAccount();
    } catch {
      Alert.alert(
        "Couldn't delete account",
        'Something went wrong on our end. Please try again.',
      );
    } finally {
      setIsDeleting(false);
    }
  };

  const confirmDeleteAccount = () => {
    // Alert.alert renders a native UIAlertController on iOS (destructive-
    // styled button, separate Cancel) and a native two-action Material
    // dialog on Android — matching each platform's own confirmation pattern
    // without branching the code.
    Alert.alert(
      'Delete account?',
      "This permanently deletes your account and all of your data. This can't be undone.",
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete Account',
          style: 'destructive',
          onPress: handleDeleteAccount,
        },
      ],
      { cancelable: true },
    );
  };

  const sections: Section[] = [
    {
      id: 'account',
      title: 'Account',
      rows: [
        { id: 'edit-profile', type: 'navigation', label: 'Edit Profile', onPress: onEditProfile },
        { id: 'change-password', type: 'navigation', label: 'Change Password', onPress: onChangePassword },
      ],
    },
    {
      id: 'preferences',
      title: 'Preferences',
      rows: [
        {
          id: 'notifications',
          type: 'toggle',
          label: 'Notifications',
          value: notificationsEnabled,
          onToggle: onToggleNotifications,
        },
        {
          id: 'biometric',
          type: 'toggle',
          label: Platform.OS === 'ios' ? 'Face ID / Touch ID' : 'Fingerprint Unlock',
          value: biometricEnabled,
          onToggle: onToggleBiometric,
        },
        { id: 'language', type: 'navigation', label: 'Language', value: 'English', onPress: onOpenLanguage },
        { id: 'privacy', type: 'navigation', label: 'Privacy', onPress: onOpenPrivacy },
      ],
    },
    {
      id: 'support',
      title: 'Support',
      rows: [
        { id: 'help', type: 'navigation', label: 'Help & Support', onPress: onOpenHelp },
        { id: 'sign-out', type: 'navigation', label: 'Sign Out', onPress: onSignOut },
      ],
    },
    {
      id: 'danger',
      title: 'Danger Zone',
      rows: [
        {
          id: 'delete-account',
          type: 'destructive',
          label: 'Delete Account',
          busy: isDeleting,
          onPress: confirmDeleteAccount,
        },
      ],
    },
  ];

  return (
    <View style={[styles.screen, { paddingTop: insets.top }]}>
      <StatusBar barStyle={scheme === 'dark' ? 'light-content' : 'dark-content'} />
      <ScrollView
        contentInsetAdjustmentBehavior="automatic"
        contentContainerStyle={{ paddingBottom: insets.bottom + 32 }}
      >
        <Text style={styles.screenTitle}>Account</Text>

        <ProfileRow
          styles={styles}
          name={user.name}
          email={user.email}
          avatarUri={user.avatarUri}
          onPress={onEditProfile}
        />

        {sections.map((section) => (
          <View key={section.id} style={styles.sectionWrapper}>
            {section.title ? (
              <Text style={styles.sectionTitle}>{section.title}</Text>
            ) : null}
            <View style={styles.sectionGroup}>
              {section.rows.map((row, index) => (
                <SettingsRowView
                  key={row.id}
                  row={row}
                  styles={styles}
                  tokens={tokens}
                  isLast={index === section.rows.length - 1}
                />
              ))}
            </View>
          </View>
        ))}
      </ScrollView>
    </View>
  );
}

// --- Profile row -----------------------------------------------------------

function ProfileRow({
  styles,
  name,
  email,
  avatarUri,
  onPress,
}: {
  styles: ReturnType<typeof createStyles>;
  name: string;
  email: string;
  avatarUri?: string;
  onPress: () => void;
}) {
  const initials = name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');

  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`${name}, ${email}. Edit profile`}
      style={({ pressed }) => [
        styles.profileRow,
        pressed && styles.rowPressed,
      ]}
    >
      {avatarUri ? (
        <Image source={{ uri: avatarUri }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback]}>
          <Text style={styles.avatarInitials}>{initials || '?'}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={styles.profileName}>{name}</Text>
        <Text style={styles.profileEmail}>{email}</Text>
      </View>
      <Text style={styles.chevron}>{CHEVRON}</Text>
    </Pressable>
  );
}

// --- Generic settings row ---------------------------------------------------

function SettingsRowView({
  row,
  styles,
  tokens,
  isLast,
}: {
  row: SettingsRow;
  styles: ReturnType<typeof createStyles>;
  tokens: Tokens;
  isLast: boolean;
}) {
  const rowStyle = ({ pressed }: { pressed: boolean }) => [
    styles.row,
    !isLast && styles.rowDivider,
    pressed && styles.rowPressed,
  ];

  if (row.type === 'toggle') {
    return (
      <View style={[styles.row, !isLast && styles.rowDivider]}>
        <Text style={styles.rowLabel}>{row.label}</Text>
        <Switch
          value={row.value}
          onValueChange={row.onToggle}
          trackColor={{ true: tokens.accentSolid }}
          accessibilityLabel={row.label}
        />
      </View>
    );
  }

  if (row.type === 'destructive') {
    return (
      <Pressable
        onPress={row.onPress}
        disabled={row.busy}
        accessibilityRole="button"
        accessibilityLabel={row.label}
        accessibilityHint="Opens a confirmation dialog before deleting your account"
        accessibilityState={{ disabled: row.busy, busy: row.busy }}
        style={rowStyle}
      >
        <Text style={[styles.rowLabel, styles.destructiveLabel]}>{row.label}</Text>
        {row.busy ? (
          <ActivityIndicator size="small" color={tokens.dangerText} />
        ) : null}
      </Pressable>
    );
  }

  return (
    <Pressable
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.value ? `${row.label}, ${row.value}` : row.label}
      style={rowStyle}
    >
      <Text style={styles.rowLabel}>{row.label}</Text>
      <View style={styles.rowTrailing}>
        {row.value ? <Text style={styles.rowValue}>{row.value}</Text> : null}
        <Text style={styles.chevron}>{CHEVRON}</Text>
      </View>
    </Pressable>
  );
}

// --- Styles -----------------------------------------------------------------

function createStyles(tokens: Tokens) {
  return StyleSheet.create({
    screen: {
      flex: 1,
      backgroundColor: tokens.bgApp,
    },
    screenTitle: {
      fontSize: 34,
      fontWeight: '700',
      color: tokens.textPrimary,
      paddingHorizontal: 16,
      paddingTop: 8,
      paddingBottom: 12,
    },
    profileRow: {
      flexDirection: 'row',
      alignItems: 'center',
      minHeight: 72,
      backgroundColor: tokens.bgSurface,
      borderRadius: 12,
      marginHorizontal: 16,
      paddingHorizontal: 16,
      paddingVertical: 12,
    },
    avatar: {
      width: 52,
      height: 52,
      borderRadius: 26,
    },
    avatarFallback: {
      backgroundColor: tokens.accentSolid,
      alignItems: 'center',
      justifyContent: 'center',
    },
    avatarInitials: {
      color: '#FFFFFF',
      fontSize: 18,
      fontWeight: '600',
    },
    profileText: {
      flex: 1,
      marginHorizontal: 12,
    },
    profileName: {
      fontSize: 17,
      fontWeight: '600',
      color: tokens.textPrimary,
      flexWrap: 'wrap',
    },
    profileEmail: {
      fontSize: 14,
      color: tokens.textMuted,
      marginTop: 2,
      flexWrap: 'wrap',
    },
    sectionWrapper: {
      marginTop: 24,
    },
    sectionTitle: {
      fontSize: 13,
      fontWeight: '600',
      textTransform: 'uppercase',
      letterSpacing: 0.4,
      color: tokens.textMuted,
      paddingHorizontal: 28,
      marginBottom: 6,
    },
    sectionGroup: {
      backgroundColor: tokens.bgSurface,
      borderRadius: 12,
      marginHorizontal: 16,
      overflow: 'hidden',
    },
    row: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'space-between',
      minHeight: 48,
      paddingHorizontal: 16,
      paddingVertical: 12,
      backgroundColor: tokens.bgSurface,
    },
    rowDivider: {
      borderBottomWidth: 1,
      borderBottomColor: tokens.borderSubtle,
    },
    rowPressed: {
      backgroundColor: tokens.bgSurfaceRaised,
    },
    rowLabel: {
      fontSize: 16,
      color: tokens.textPrimary,
      flexShrink: 1,
      flexWrap: 'wrap',
    },
    rowTrailing: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: 6,
    },
    rowValue: {
      fontSize: 15,
      color: tokens.textMuted,
    },
    chevron: {
      fontSize: 18,
      color: tokens.textMuted,
    },
    destructiveLabel: {
      color: tokens.dangerText,
      fontWeight: '500',
    },
  });
}
```

A few notes on using it:
- Pass `onDeleteAccount` as an async function that calls your API; the row disables itself and shows a spinner while it's in flight, and surfaces an alert on failure.
- Wrap the app root in `SafeAreaProvider` from `react-native-safe-area-context` (standard if you're already using React Navigation).
- Icons were intentionally left out to avoid an unneeded dependency — swap in SF Symbols/Material icons via `react-native-vector-icons` or `@expo/vector-icons` if you want leading glyphs on each row; the row layout already reserves space for them via `flexDirection: 'row'`.
